def main():
    input = sys.stdin.readline
    N = int(input())
    P = list(map(int, input().split()))

    bit = [0] * (N + 2)

    def add(i, v):
        while i <= N:
            bit[i] += v
            i += i & -i

    def sum_prefix(i):
        s = 0
        while i > 0:
            s += bit[i]
            i -= i & -i
        return s

    ans = 0
